param([Parameter(Mandatory=$true)][ValidateSet('CPU','GPU')][string]$Backend,[Parameter(Mandatory=$true)][ValidateSet('smoke','eta0','coarse','half')][string]$Window,[Parameter(Mandatory=$true)][string]$Admission,[switch]$ExecutionAuthorized)
# One fresh actual project-main call. No automatic reader, next job, build or install.
$ErrorActionPreference='Stop';$Backend=$Backend.ToUpperInvariant();$Window=$Window.ToLowerInvariant();$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$src=Join-Path $repo 'src';$logs=Join-Path $tests 'logs'
$tag='upl_damp_'+$Backend+'_'+$Window+'_r1';$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log')
$smoke=$Window -ceq 'smoke';$cfg=if($Backend -ceq 'CPU'){if($smoke){'DebugCPU'}else{'ReleaseCPU'}}else{if($smoke){'Debug'}else{'Release'}}
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $e.sha256) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 16)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
Need $ExecutionAuthorized.IsPresent 'Explicit execution authorization required';Fresh @($folder,$record,$callPath,$log)
$gate=J $Admission;Need ($gate.stage -ceq 'upl_damp_admission_r1' -and $gate.passed -and $gate.allowed_jobs -ccontains $tag -and $gate.physical_acceptance -eq $false) 'This exact bounded job needs root admission';V $gate.inputs
$buildPath=Join-Path $logs ('upl_damp_'+$cfg+'_r2.build.json');$b=J $buildPath;Need ($b.passed -and $b.configuration -ceq $cfg -and $b.program.path -and @($b.source_snapshot).Count -eq 265 -and @($b.canonical_programs_before).Count -eq 7 -and @($b.runtime).Count -eq 4) 'Passed corrected same-stage authoritative build required'
$manifest=Join-Path $logs 'upl_damp_r1.inputs.json';$m=J $manifest;Need ($m.passed -and $m.prepared) 'Own prepared inputs required';$rows=@($m.jobs|Where-Object {$_.window -ceq $Window});Need ($rows.Count -eq 1) 'Unique bounded window required';$job=$rows[0]
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_plan_r1.json')),(E $Admission),(E $buildPath),(E $manifest),$b.program,$job.configuration,$job.runtime,$job.initial_BI4,$job.normals)+@($gate.inputs)+@($m.inputs)+@($b.inputs)+@($b.objects)+@($b.canonical_programs_before)
foreach($p in $b.source_snapshot){$bindings+=@($p.original,$p.snapshot)};$bindings+=@($b.documentation_snapshot.original,$b.documentation_snapshot.snapshot);foreach($p in $b.runtime){$bindings+=@($p.original,$p.copy)}
$argsTarget=@(if($Backend -ceq 'CPU'){'-cpu';'-ompthreads:8'}else{'-gpu:0'});$argsTarget+=@('-stable','-mdbc_freeslip',$job.input_prefix,$folder,'-dirdataout','data','-svres',('-nsteps:'+$job.steps))
$mem=($Backend -ceq 'GPU' -and $smoke);$tool=$b.program;$argv=$argsTarget
if($mem){$tool=E 'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v11.7\compute-sanitizer\compute-sanitizer.exe';Need ($tool.sha256 -ceq 'db5aaaf6fa07566eb10b71f5864e2229d8f061950618bb1270a56a25acd17589') 'Reviewed CUDA11.7 memcheck tool differs';$bindings+=@($tool);$argv=@('--tool','memcheck','--leak-check','full','--error-exitcode','99',$b.program.path)+$argsTarget}
V $bindings;$active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe'");Need ($active.Count -eq 0) 'Another project solver/helper is active; no duplicate launch'
$started=[DateTime]::UtcNow.ToString('o');$code=$null;$failure=$null;$saved=$ErrorActionPreference;[IO.File]::WriteAllBytes($log,[byte[]]@());Push-Location $src
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$tool;target_program=$b.program;arguments=$argv;target_arguments=$argsTarget;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);public_project_main=$true;fixture_or_Run_override=$false;memcheck_executed=$mem;direct_target_call=(!$mem);target_child_exit_separately_observed=$false;physical_acceptance=$false})
# Original typed tool result is sealed before output inspection.
$files=@();$runOut=$null;$zero=$false;$unchanged=$false;$loop=$null;$total=$null;$rawCount=0;$rate=$null
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Owned actual call failed; inspect and preserve partials'
  $text=[IO.File]::ReadAllText($log);$zero=(!$mem -or ($text -match 'ERROR SUMMARY: 0 errors' -and $text -match 'LEAK SUMMARY: 0 bytes leaked in 0 allocations'));Need $zero 'GPU memory check rejected'
  $runOut=E (Join-Path $folder 'Run.out');$run=[IO.File]::ReadAllText($runOut.path);Need ($run -match '(?m)^\[Simulation finished\s') 'Normal solver completion missing'
  foreach($label in @('Simulation Runtime','Total Runtime')){$v=[regex]::Match($run,('(?m)^'+$label+'[.]+:\s*([0-9.]+)\s+sec[.]\s*$'));Need $v.Success ('Actual runtime missing: '+$label);$seconds=[double]::Parse($v.Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);if($label -ceq 'Simulation Runtime'){$loop=$seconds}else{$total=$seconds}}
  $v=[regex]::Match($run,'Dynamic soil damping rate: ([0-9.eE+-]+) s\^-1');Need $v.Success 'Actual intrinsic damping-rate diagnostic missing';$rate=[double]::Parse($v.Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);Need ($(if($Window -ceq 'eta0'){$rate -eq 0}else{$rate -gt 30 -and $rate -lt 32})) 'Declared single damping candidate differs'
  if($Backend -ceq 'CPU'){Need ($run -match 'OpenMP\(Threads:8\)') 'Actual CPU8 mode missing'}else{Need ($run -match 'NVIDIA GeForce RTX 3050') 'Actual local GPU device differs'}
  $raw=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$rawCount=$raw.Count;$wanted=@(0..($job.expected_samples-1)|ForEach-Object {'Part_{0:D4}.bi4' -f $_});Need ($rawCount -eq $job.expected_samples -and !(Compare-Object ($raw.Name|Sort-Object) ($wanted|Sort-Object))) 'Raw native frame sequence differs; no automatic rerun'
}catch{$failure=$_.Exception.Message}
try{V $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
if(Test-Path -LiteralPath $folder){$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse|Sort-Object FullName|ForEach-Object {E $_.FullName})}
$passed=(!$failure -and $unchanged -and $rawCount -eq $job.expected_samples -and $zero)
Save $record ([ordered]@{stage='upl_damp_run_r1';passed=[bool]$passed;backend=$Backend;window=$Window;configuration=$cfg;program=$b.program;source_build=(E $buildPath);source_snapshot=$b.source_snapshot;documentation_snapshot=$b.documentation_snapshot;runtime=$b.runtime;canonical_programs_before=$b.canonical_programs_before;input_manifest=(E $manifest);job=$job;admission=(E $Admission);call=(E $callPath);inputs=$bindings;files=$files;run_out=$runOut;native_frames=$rawCount;memcheck_executed=$mem;memcheck_zero_errors_and_leaks=[bool]($mem -and $zero);actual_damping_rate_s_inv=$rate;simulation_runtime_s=$loop;total_runtime_s=$total;source_inputs_objects_runtime_canonical_unchanged=$unchanged;public_project_main=$true;fixture_or_Run_override=$false;native_decoder_invoked=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Actual run rejected; preserve $record, no automatic retry"};Write-Output "One actual damping job sealed: $record"
